const rawInput = $input.first().json || {};
const payload = (rawInput.body && typeof rawInput.body === 'object') ? rawInput.body : rawInput;

const toHalfWidthAscii = (s) => String(s || '')
  .replace(/[！-～]/g, (ch) => String.fromCharCode(ch.charCodeAt(0) - 0xfee0))
  .replace(/　/g, ' ');

// 1. NTA Qualified Invoice T-Number Modulo-9 Verification
const rawT = toHalfWidthAscii(payload.invoiceTNumber || payload.tNumber || '');
const tMatch = rawT.match(/T[-\s]?(\d{13})\b/i);
let tNumberNormalized = '';
let tNumberValid = false;
let expectedCheckDigit = null;
if (tMatch) {
  const digits = tMatch[1];
  tNumberNormalized = `T${digits}`;
  const actualCd = Number(digits[0]);
  let total = 0;
  for (let idx = 1; idx < 13; idx += 1) {
    const q = Number(digits[13 - idx]);
    total += q * (idx % 2 === 1 ? 1 : 2);
  }
  expectedCheckDigit = 9 - (total % 9);
  tNumberValid = (actualCd === expectedCheckDigit);
}

// 2. Wareki / Gregorian Date Parser -> YYYYMMDD
const parseDateYmd = (raw) => {
  const norm = toHalfWidthAscii(raw);
  const eraBase = { '令和': 2018, 'R': 2018, '平成': 1988, 'H': 1988 };
  const wm = norm.match(/(令和|平成)\s*(元|\d{1,2})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*日?/);
  if (wm) {
    const y = eraBase[wm[1]] + (wm[2] === '元' ? 1 : Number(wm[2]));
    return `${y}${String(wm[3]).padStart(2, '0')}${String(wm[4]).padStart(2, '0')}`;
  }
  const ws = norm.match(/\b([RHrh])\s*(\d{1,2})[./-](\d{1,2})[./-](\d{1,2})\b/);
  if (ws) {
    const y = eraBase[ws[1].toUpperCase()] + Number(ws[2]);
    return `${y}${String(ws[3]).padStart(2, '0')}${String(ws[4]).padStart(2, '0')}`;
  }
  const gm = norm.match(/(20\d{2})\s*[-/年.]\s*(\d{1,2})\s*[-/月.]\s*(\d{1,2})\s*日?/);
  if (gm) {
    return `${gm[1]}${String(gm[2]).padStart(2, '0')}${String(gm[3]).padStart(2, '0')}`;
  }
  const cm = norm.match(/\b(20\d{2})(\d{2})(\d{2})\b/);
  return cm ? `${cm[1]}${cm[2]}${cm[3]}` : '';
};

const transactionDate = parseDateYmd(payload.invoiceDate || payload.date || '');
const vendorRaw = String(payload.vendorName || '').trim();
const vendorClean = vendorRaw.replace(/[\\/:*?"<>|\s]+/g, '').slice(0, 48);
const amountNum = Number(String(payload.amountYen || payload.amount || '').replace(/[^0-9]/g, ''));
const amountValid = Number.isFinite(amountNum) && amountNum > 0;

const errors = [];
if (!tNumberValid) {
  errors.push(tNumberNormalized
    ? `Invalid NTA T-number check digit for ${tNumberNormalized} (expected leading digit ${expectedCheckDigit})`
    : 'Missing NTA Qualified Invoice T-number (T + 13 digits)');
}
if (!transactionDate) errors.push('Missing or unparseable invoiceDate (required for Dencho-ho 3-key search)');
if (!vendorClean) errors.push('Missing vendorName (required for Dencho-ho 3-key search)');
if (!amountValid) errors.push('Missing positive integer amountYen (required for Dencho-ho 3-key search)');

const denchoFilename = (transactionDate && vendorClean && amountValid)
  ? `${transactionDate}_${vendorClean}_${amountNum}.pdf`
  : '';

return [{
  json: {
    isValidInvoice: errors.length === 0,
    validationErrors: errors,
    tNumberNormalized,
    tNumberValid,
    expectedCheckDigit,
    transactionDate,
    vendorName: vendorRaw,
    vendorClean,
    amountYen: amountValid ? amountNum : 0,
    denchoFilename,
    payeeBankCode: String(payload.payeeBankCode || '').replace(/\D/g, '').padStart(4, '0').slice(-4),
    payeeBranchCode: String(payload.payeeBranchCode || '').replace(/\D/g, '').padStart(3, '0').slice(-3),
    payeeAccountType: String(payload.payeeAccountType || '1'),
    payeeAccountNo: String(payload.payeeAccountNo || '').replace(/\D/g, '').padStart(7, '0').slice(-7),
    payeeKana: String(payload.payeeKana || vendorRaw),
    transferDateMmdd: String(payload.transferDateMmdd || (transactionDate ? transactionDate.slice(4, 8) : '1125'))
  }
}];

const item = $input.first().json;

const KANA_MAP = {
  'ア': 'ｱ', 'イ': 'ｲ', 'ウ': 'ｳ', 'エ': 'ｴ', 'オ': 'ｵ',
  'カ': 'ｶ', 'キ': 'ｷ', 'ク': 'ｸ', 'ケ': 'ｹ', 'コ': 'ｺ',
  'サ': 'ｻ', 'シ': 'ｼ', 'ス': 'ｽ', 'セ': 'ｾ', 'ソ': 'ｿ',
  'タ': 'ﾀ', 'チ': 'ﾁ', 'ツ': 'ﾂ', 'テ': 'ﾃ', 'ト': 'ﾄ',
  'ナ': 'ﾅ', 'ニ': 'ﾆ', 'ヌ': 'ﾇ', 'ネ': 'ﾈ', 'ノ': 'ﾉ',
  'ハ': 'ﾊ', 'ヒ': 'ﾋ', 'フ': 'ﾌ', 'ヘ': 'ﾍ', 'ホ': 'ﾎ',
  'マ': 'ﾏ', 'ミ': 'ﾐ', 'ム': 'ﾑ', 'メ': 'ﾒ', 'モ': 'ﾓ',
  'ヤ': 'ﾔ', 'ユ': 'ﾕ', 'ヨ': 'ﾖ',
  'ラ': 'ﾗ', 'リ': 'ﾘ', 'ル': 'ﾙ', 'レ': 'ﾚ', 'ロ': 'ﾛ',
  'ワ': 'ﾜ', 'ヲ': 'ｦ', 'ン': 'ﾝ',
  'ガ': 'ｶﾞ', 'ギ': 'ｷﾞ', 'グ': 'ｸﾞ', 'ゲ': 'ｹﾞ', 'ゴ': 'ｺﾞ',
  'ザ': 'ｻﾞ', 'ジ': 'ｼﾞ', 'ズ': 'ｽﾞ', 'ゼ': 'ｾﾞ', 'ゾ': 'ｿﾞ',
  'ダ': 'ﾀﾞ', 'ヂ': 'ﾁﾞ', 'ヅ': 'ﾂﾞ', 'デ': 'ﾃﾞ', 'ド': 'ﾄﾞ',
  'バ': 'ﾊﾞ', 'ビ': 'ﾋﾞ', 'ブ': 'ﾌﾞ', 'ベ': 'ﾍﾞ', 'ボ': 'ﾎﾞ',
  'パ': 'ﾊﾟ', 'ピ': 'ﾋﾟ', 'プ': 'ﾌﾟ', 'ペ': 'ﾍﾟ', 'ポ': 'ﾎﾟ',
  'ァ': 'ｱ', 'ィ': 'ｲ', 'ゥ': 'ｳ', 'ェ': 'ｴ', 'ォ': 'ｵ',
  'ッ': 'ﾂ', 'ャ': 'ﾔ', 'ュ': 'ﾕ', 'ョ': 'ﾖ', 'ー': '-'
};

const toZenginKana = (raw, maxLen) => {
  let s = String(raw || '')
    .replace(/^株式会社\s*/, 'ｶ)')
    .replace(/\s*株式会社$/, '(ｶ')
    .replace(/^合同会社\s*/, 'ﾄﾞ)')
    .replace(/[ぁ-ん]/g, (ch) => String.fromCharCode(ch.charCodeAt(0) + 0x60))
    .replace(/[！-～]/g, (ch) => String.fromCharCode(ch.charCodeAt(0) - 0xfee0))
    .toUpperCase();
  let out = '';
  for (const ch of s) {
    if (KANA_MAP[ch]) out += KANA_MAP[ch];
    else if (/^[A-Z0-9 .\-()\/ｱ-ﾝﾞﾟ]$/.test(ch)) out += ch;
  }
  return out.slice(0, maxLen).padEnd(maxLen, ' ');
};

const encodeCp932SingleByte = (str) => {
  const bytes = [];
  for (const ch of str) {
    const code = ch.charCodeAt(0);
    if (code >= 0x20 && code <= 0x7e) bytes.push(code);
    else if (code === 0x0d || code === 0x0a) bytes.push(code);
    else if (code >= 0xff61 && code <= 0xff9f) bytes.push(code - 0xff61 + 0xa1);
    else bytes.push(0x20);
  }
  return Buffer.from(bytes);
};

const clientCode = String($env.ZENGIN_CLIENT_CODE || '0000000001').replace(/\D/g, '').padStart(10, '0').slice(-10);
const senderKana = toZenginKana($env.ZENGIN_SENDER_KANA || 'ﾎﾗｲｽﾞﾝｶﾌﾞｼｷｶﾞｲｼﾔ', 40);
const transferMmdd = String(item.transferDateMmdd || '1125').replace(/\D/g, '').padStart(4, '0').slice(-4);
const senderBank = String($env.ZENGIN_SENDER_BANK_CODE || '0005').replace(/\D/g, '').padStart(4, '0').slice(-4);
const senderBranch = String($env.ZENGIN_SENDER_BRANCH_CODE || '001').replace(/\D/g, '').padStart(3, '0').slice(-3);
const senderAcct = String($env.ZENGIN_SENDER_ACCOUNT_NO || '1234567').replace(/\D/g, '').padStart(7, '0').slice(-7);

const headerRec = (
  '1' + '21' + '0' + clientCode + senderKana + transferMmdd +
  senderBank + ' '.repeat(15) + senderBranch + ' '.repeat(15) + '1' + senderAcct + ' '.repeat(17)
).slice(0, 120).padEnd(120, ' ');

const payeeKana = toZenginKana(item.payeeKana, 30);
const amount10 = String(item.amountYen).padStart(10, '0').slice(-10);
const dataRec = (
  '2' + item.payeeBankCode + ' '.repeat(15) + item.payeeBranchCode + ' '.repeat(15) +
  '    ' + item.payeeAccountType.slice(0, 1) + item.payeeAccountNo + payeeKana + amount10 +
  '0' + ' '.repeat(20) + ' ' + ' ' + ' '.repeat(7)
).slice(0, 120).padEnd(120, ' ');

const trailerRec = ('8' + '000001' + String(item.amountYen).padStart(12, '0').slice(-12) + ' '.repeat(101)).slice(0, 120);
const endRec = ('9' + ' '.repeat(119)).slice(0, 120);

const fullText = [headerRec, dataRec, trailerRec, endRec].join('\r\n') + '\r\n';
const cp932Buf = encodeCp932SingleByte(fullText);
const zenginFilename = `zengin_${item.transactionDate}_${item.payeeBankCode}.txt`;

return [{
  json: {
    ...item,
    zenginFilename,
    zenginByteLength: cp932Buf.length,
    zenginRecordCount: 1,
    zenginBase64Cp932: cp932Buf.toString('base64'),
    zenginPreviewHeader: headerRec
  }
}];
